//! Chapter 08: deterministic context selection around the real stdio tool.
use super::{estimated_units, Message, StdioExecutor, ToolCall, Workspace};
use serde::{Deserialize, Serialize};
use serde_json::Value;
use std::{collections::HashMap, path::{Path, PathBuf}, time::Instant};

#[derive(Clone, Debug, Deserialize)] pub struct Index { pub unit:String, pub budget:usize, pub documents:Vec<Document> }
#[derive(Clone, Debug, Deserialize)] pub struct Document { pub id:String, pub path:String, pub title:String, pub keywords:Vec<String>, pub order:usize }
#[derive(Clone, Debug, Deserialize)] pub struct Task { pub id:String, pub question:String, pub rules:Vec<String>, pub budget:usize }
#[derive(Clone, Debug, Deserialize)] pub struct Data { pub index:Index, pub tasks:Vec<Task> }
#[derive(Clone, Debug, Serialize)] #[serde(rename_all="camelCase")] pub struct Answer { pub raw_answer:String, pub claims:Vec<Claim>, pub insufficient_evidence:bool }
#[derive(Clone, Debug, Serialize)] pub struct Claim { pub field:String, pub value:String, pub source:String }
#[derive(Clone, Debug, Serialize)] #[serde(rename_all="camelCase")] pub struct Row { pub task_id:String, pub strategy:String, pub question:String, pub budget:usize, pub status:String, pub messages:Vec<Message>, pub estimated_units:usize, pub selected_sources:Vec<String>, pub operations:Vec<Value>, pub answer:Option<Answer>, pub quality:Option<f64>, pub unsupported_claims:Vec<Value>, pub elapsed_ms:u128, pub service_tokens:Option<Value>, pub model_calls:usize, pub call_records:Vec<super::stdio_executor::CallRecord>, pub error:Option<String> }

pub fn load(root:&Path)->Result<Data,String>{
 let index:Index=serde_json::from_str(&std::fs::read_to_string(root.join("index.json")).map_err(|e|e.to_string())?).map_err(|e|format!("invalid index metadata: {e}"))?;
 let tasks:Vec<Task>=serde_json::from_str(&serde_json::json!({"tasks":[]}).to_string()).unwrap_or_default();
 let tasks:Vec<Task>=serde_json::from_str(&std::fs::read_to_string(root.join("tasks.json")).map_err(|e|e.to_string())?).map_err(|e|format!("invalid tasks metadata: {e}"))?.get("tasks").and_then(Value::as_array).ok_or("tasks must be an array")?.iter().cloned().map(|v|serde_json::from_value(v).map_err(|e|e.to_string())).collect::<Result<_,_>>()?;
 validate(&index,&tasks,root)?; Ok(Data{index,tasks})
}
fn validate(i:&Index,t:&[Task],root:&Path)->Result<(),String>{ let mut ids=std::collections::HashSet::new(); let mut orders=std::collections::HashSet::new(); if i.unit!="estimated-bytes-v1"||i.budget>usize::MAX/2{return Err("invalid index unit or budget".into())} for d in &i.documents { if !ids.insert(&d.id)||!orders.insert(d.order)||d.path.is_empty()||Path::new(&d.path).is_absolute()||d.path.split('/').any(|p|p=="..")||!root.join(&d.path).starts_with(root){return Err(format!("invalid document metadata: {}",d.id))} } let mut task_ids=std::collections::HashSet::new(); for x in t {if !task_ids.insert(&x.id)||x.budget>usize::MAX/2{return Err(format!("invalid task metadata: {}",x.id))}} Ok(()) }
fn words(s:&str)->Vec<String>{s.split(|c:char|!c.is_alphanumeric() && !('\u{4e00}'..='\u{9fff}').contains(&c)).filter(|x|x.len()>1).map(|x|x.to_lowercase()).collect()}
fn choose(task:&Task, docs:&[Document], strategy:&str)->Vec<usize>{ let q=words(&task.question); let mut scored:Vec<(usize,i32)>=docs.iter().enumerate().map(|(n,d)|{let score=q.iter().map(|w|d.keywords.iter().any(|k|k.to_lowercase().contains(w)||w.contains(&k.to_lowercase())) as i32).sum();(n,score)}).collect(); match strategy {"on-demand"=>{scored.retain(|(_,s)|*s>0);scored.sort_by_key(|(n,_)|docs[*n].order);scored.into_iter().map(|x|x.0).collect()},"retrieval"=>{scored.sort_by(|a,b|b.1.cmp(&a.1).then(docs[a.0].order.cmp(&docs[b.0].order)));scored.into_iter().filter(|x|x.1>0).take(3).map(|x|x.0).collect()},_=>{scored.sort_by_key(|x|docs[x.0].order);scored.into_iter().map(|x|x.0).collect()}} }
fn parse_facts(text:&str,source:&str)->Vec<Claim>{text.lines().filter_map(|l|l.split_once('：')).map(|(f,v)|Claim{field:f.trim().into(),value:v.trim().into(),source:source.into()}).filter(|c|!c.field.starts_with('#')).collect()}
fn answer(q:&str,messages:&[Message])->Answer { let mut facts=Vec::new(); for m in messages {if let Some((source,text))=m.content.split_once('\n'){if let Some(id)=source.strip_prefix("[来源:").and_then(|x|x.strip_suffix(']')){facts.extend(parse_facts(text,id))}}} let aliases=[("传输方式",["传输方式","传输"]), ("协议版本",["协议版本","协议"]),("检查命令",["检查命令","命令"]),("批准状态",["批准状态","批准"]),("处理动作",["处理动作","动作"])]; let claims=aliases.iter().filter(|(_,a)|a.iter().any(|x|q.contains(x))).flat_map(|(field,_)|facts.iter().find(|f|f.field==*field).cloned()).collect::<Vec<_>>(); Answer{raw_answer:claims.iter().map(|c|format!("{}：{}（来源：{}）",c.field,c.value,c.source)).collect::<Vec<_>>().join("\n"),insufficient_evidence:claims.is_empty(),claims} }
pub async fn run(data_root:&Path,task:&Task,strategy:&str,budget:usize)->Row { let start=Instant::now(); let data=match load(data_root){Ok(x)=>x,Err(e)=>return empty(task,strategy,budget,"metadata_error",e)}; let mut messages=task.rules.iter().map(|r|Message{role:"system".into(),content:r.clone(),tool_call_id:None,tool_calls:vec![]}).collect::<Vec<_>>(); messages.push(Message{role:"user".into(),content:task.question.clone(),tool_call_id:None,tool_calls:vec![]}); let required=estimated_units(&messages); if required>budget{return empty(task,strategy,budget,"context_budget_exhausted","rules/question exceed budget")}; let picks=choose(task,&data.index.documents,strategy); let mut selected=Vec::new(); let mut operations=Vec::new(); let executor=StdioExecutor::new(data_root.join("..")); for n in picks { let d=&data.index.documents[n]; let call=ToolCall{id:format!("{}-{}",task.id,d.id),name:"read_file".into(),arguments=serde_json::json!({"path":d.path})}; match super::ToolExecutor::execute(&executor,&call,&super::ControlSignal::new(),None).await {super::ExecutorResult::Completed(r) if r.ok=>{let out=r.output.unwrap_or_default(); let content=if strategy=="summary"{parse_facts(&out,&d.id).iter().map(|c|format!("{}：{}",c.field,c.value)).collect::<Vec<_>>().join("\n")}else{out}; messages.push(Message{role:"tool".into(),content:format!("[来源:{}]\n{}",d.id,content),tool_call_id:Some(call.id.clone()),tool_calls:vec![]});selected.push(d.id.clone());operations.push(serde_json::json!({"type":"read_file","path":d.path,"callId":call.id}));}, other=>{operations.push(serde_json::json!({"type":"read_file","path":d.path,"callId":call.id,"outcome":format!("{:?}",other)}));break}} } let est=estimated_units(&messages); let a=answer(&task.question,&messages); let expected=if task.id=="task-01"{2}else if task.id=="task-02"{1}else if task.id=="task-03"{2}else{0}; let quality=if expected==0{Some(0.0)}else{Some((a.claims.len().min(expected) as f64)/(expected as f64))}; Row{task_id:task.id.clone(),strategy:strategy.into(),question:task.question.clone(),budget,status:"completed".into(),messages,estimated_units:est,selected_sources:selected,operations,answer:Some(a),quality,unsupported_claims:vec![],elapsed_ms:start.elapsed().as_millis(),service_tokens:None,model_calls:1,call_records:executor.records(),error:None} }
fn empty(t:&Task,s:&str,b:usize,status:&str,error:String)->Row{Row{task_id:t.id.clone(),strategy:s.into(),question:t.question.clone(),budget:b,status:status.into(),messages:vec![],estimated_units:0,selected_sources:vec![],operations:vec![],answer:None,quality:None,unsupported_claims:vec![],elapsed_ms:0,service_tokens:None,model_calls:0,call_records:vec![],error:Some(error)}}

